include "globals.mzn";

% Input data
int: num_floors = 5;
set of int: Floors = 1..num_floors;

% Decision Variables
array[1..5] of var Floors: floors; % floors[1] = Baker, floors[2] = Cooper, floors[3] = Fletcher, floors[4] = Miller, floors[5] = Smith

% Constraints
constraint all_different(floors); % They all live on different floors

% Baker does not live on the fifth floor
constraint floors[1] != 5;

% Cooper does not live on the first floor
constraint floors[2] != 1;

% Fletcher does not live on either the fifth or the first floor
constraint floors[3] != 1;
constraint floors[3] != 5;

% Miller lives on a higher floor than does Cooper
constraint floors[4] > floors[2];

% Smith does not live on a floor adjacent to Fletcher’s
constraint abs(floors[5] - floors[3]) != 1;

% Fletcher does not live on a floor adjacent to Cooper’s
constraint abs(floors[3] - floors[2]) != 1;

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "B" ++ "\": " ++ show(floors[1]),
        "\"" ++ "C" ++ "\": " ++ show(floors[2]),
        "\"" ++ "F" ++ "\": " ++ show(floors[3]),
        "\"" ++ "M" ++ "\": " ++ show(floors[4]),
        "\"" ++ "S" ++ "\": " ++ show(floors[5])
    ]),
    "}"
];
```

