include "globals.mzn";

% Input data
int: num_people = 8;
array[1..num_people] of set of 1..num_people: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision Variables
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints
% Each person can donate to at most one person
constraint forall(i in 1..num_people) (
    sum(j in 1..num_people) (transplants[i, j]) <= 1
);

% Each person can receive from at most one person
constraint forall(j in 1..num_people) (
    sum(i in 1..num_people) (transplants[i, j]) <= 1
);

% If person i donates to person j, then j must be in the compatible set of i
constraint forall(i in 1..num_people, j in 1..num_people) (
    transplants[i, j] = 1 -> j in compatible[i]
);

% If person i donates to person j, then person j must donate to someone else
constraint forall(i in 1..num_people, j in 1..num_people) (
    transplants[i, j] = 1 -> exists(k in 1..num_people where k != i) (transplants[j, k] = 1)
);

% Objective: Maximize the number of transplants
var int: total_transplants = sum(i in 1..num_people, j in 1..num_people) (transplants[i, j]);

solve maximize total_transplants;

% Output the solution in JSON format
output [
    "{",
    "\"transplants\": [" ++ join(",", [ "[" ++ join(",", [show(transplants[i, j]) | j in 1..num_people]) ++ "]" | i in 1..num_people]) ++ "]",
    "}"
];
```

