% Include necessary libraries
include "globals.mzn";

% Input data
int: target_amount = 199;
array[1..6] of int: coin_values = [1, 2, 5, 10, 25, 50];
array[1..6] of int: coin_availability = [20, 10, 15, 8, 4, 2];

% Decision Variables
array[1..6] of var 0..max(coin_availability): coin_counts;

% Constraints
% The total value of the coins should be equal to the target amount
constraint sum(i in 1..6)(coin_counts[i] * coin_values[i]) = target_amount;

% The number of each type of coin used should not exceed the available amount
constraint forall(i in 1..6)(coin_counts[i] <= coin_availability[i]);

% Objective: Minimize the total number of coins used
solve minimize sum(i in 1..6)(coin_counts[i]);

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "coin_counts" ++ "\": [" ++ join(",", [show(coin_counts[i]) | i in 1..6]) ++ "]"
    ]),
    "}"
