include "globals.mzn";

% Input data
int: num_jobs = 3;
int: num_tasks = 3;
int: num_machines = 3;

array[1..num_jobs, 1..num_tasks] of int: job_task_machine;
array[1..num_jobs, 1..num_tasks] of int: job_task_duration;

% Initialize the job_task_machine and job_task_duration arrays based on the input data
constraint job_task_machine[1, 1] = 0 /\ job_task_duration[1, 1] = 3;
constraint job_task_machine[1, 2] = 1 /\ job_task_duration[1, 2] = 2;
constraint job_task_machine[1, 3] = 2 /\ job_task_duration[1, 3] = 2;

constraint job_task_machine[2, 1] = 0 /\ job_task_duration[2, 1] = 2;
constraint job_task_machine[2, 2] = 2 /\ job_task_duration[2, 2] = 1;
constraint job_task_machine[2, 3] = 1 /\ job_task_duration[2, 3] = 4;

constraint job_task_machine[3, 1] = 1 /\ job_task_duration[3, 1] = 4;
constraint job_task_machine[3, 2] = 2 /\ job_task_duration[3, 2] = 3;

% Decision Variables
array[1..num_jobs, 1..num_tasks] of var 0..100: start_times;
var 0..100: makespan;

% Constraints
% No task for a job can be started until the previous task for that job is completed.
constraint forall(j in 1..num_jobs, t in 2..num_tasks) (
    start_times[j, t] >= start_times[j, t-1] + job_task_duration[j, t-1]
);

% A machine can only work on one task at a time.
constraint forall(m in 0..num_machines-1) (
    alldifferent_except_0([start_times[j, t] + job_task_duration[j, t] * (job_task_machine[j, t] == m) | j in 1..num_jobs, t in 1..num_tasks])
);

% A task, once started, must run to completion.
% This is already ensured by the definition of start_times and job_task_duration.

% Define the makespan as the maximum completion time of all tasks
constraint makespan = max([start_times[j, t] + job_task_duration[j, t] | j in 1..num_jobs, t in 1..num_tasks]);

% Solve the model to minimize the makespan
solve minimize makespan;

% Print the solution in JSON format
output [
    "{",
    "\"" ++ "makespan" ++ "\": " ++ show(makespan),
    "}"
];
```

