include "globals.mzn";

% Input data
int: N = 20;  % Number of steps to the solution
array[1..3, 1..3] of int: puzzle_start = [
    [0, 3, 6],
    [2, 4, 8],
    [1, 7, 5]
];

array[1..3, 1..3] of int: puzzle_end = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 0]
];

% Decision Variables
array[0..N, 1..3, 1..3] of var 0..8: puzzle_states;
array[0..N, 1..2] of var 1..3: empty_positions;

% Initial state
constraint puzzle_states[0, 1..3, 1..3] = puzzle_start;

% Final state
constraint puzzle_states[N, 1..3, 1..3] = puzzle_end;

% Find the initial position of the empty tile
constraint empty_positions[0, 1] = sum(i in 1..3, j in 1..3 where puzzle_start[i, j] = 0) (i);
constraint empty_positions[0, 2] = sum(i in 1..3, j in 1..3 where puzzle_start[i, j] = 0) (j);

% Constraints for each step
constraint forall(t in 0..N-1) (
    let {
        var 1..3: ei = empty_positions[t, 1];
        var 1..3: ej = empty_positions[t, 2];
        var 1..3: ni = empty_positions[t+1, 1];
        var 1..3: nj = empty_positions[t+1, 2];
        var 0..8: tile = puzzle_states[t, ni, nj]
    } in
    (
        % The empty tile moves to an adjacent position
        (abs(ei - ni) + abs(ej - nj) = 1) /\
        % The new position of the empty tile is within bounds
        (ni >= 1 /\ ni <= 3 /\ nj >= 1 /\ nj <= 3) /\
        % The puzzle state at the next step is the same as the current step except for the swapped tiles
        (forall(i in 1..3, j in 1..3) (
            (i != ei \/ j != ej) -> puzzle_states[t+1, i, j] = puzzle_states[t, i, j]
        )) /\
        % The empty tile swaps with the adjacent tile
        (puzzle_states[t+1, ei, ej] = tile) /\
        (puzzle_states[t+1, ni, nj] = 0)
    )
);

% Output the states of the puzzle at each step
output [
    "{",
    "\"steps\": [",
    join(",", [
        "[" ++ join(",", [
            "[" ++ join(",", [show(puzzle_states[t, i, j]) | j in 1..3]) ++ "]"
            | i in 1..3
        ]) ++ "]"
        | t in 0..N
    ]),
    "]",
    "}"
];
