% Input data
int: num_items = 4;
array[1..num_items] of int: widths = [3, 4, 2, 1];
array[1..num_items] of int: heights = [2, 3, 1, 4];

% Decision Variables
array[1..num_items] of var 0..100: pos_x; % x-coordinate of the bottom-left corner of each item
array[1..num_items] of var 0..100: pos_y; % y-coordinate of the bottom-left corner of each item
var 0..100: total_x; % Width of the larger rectangle
var 0..100: total_y; % Height of the larger rectangle

% Constraints
% Ensure all items are within the larger rectangle
constraint forall(i in 1..num_items) (
    pos_x[i] + widths[i] <= total_x /\ pos_y[i] + heights[i] <= total_y
);

% Ensure no items overlap
constraint forall(i, j in 1..num_items where i < j) (
    pos_x[i] + widths[i] <= pos_x[j] \/ pos_x[j] + widths[j] <= pos_x[i] \/
    pos_y[i] + heights[i] <= pos_y[j] \/ pos_y[j] + heights[j] <= pos_y[i]
);

% Objective: Minimize the area of the larger rectangle
solve minimize total_x * total_y;

% Output the positions of the items and the dimensions of the larger rectangle
output [
    "{",
    join(",", [
        "\"" ++ "pos_x" ++ "\": [" ++ join(",", [show(pos_x[i]) | i in 1..num_items]) ++ "]",
        "\"" ++ "pos_y" ++ "\": [" ++ join(",", [show(pos_y[i]) | i in 1..num_items]) ++ "]",
        "\"" ++ "total_x" ++ "\": " ++ show(total_x),
        "\"" ++ "total_y" ++ "\": " ++ show(total_y)
    ]),
    "}"
];
