    array2d(1..18, 1..2, [0, 1, 0, 2, 0, 3, 1, 4, 1, 5, 2, 9, 2, 10, 3, 8, 4, 6, 4, 7, 5, 9, 5, 10, 6, 8, 6, 9, 7, 8, 8, 11, 9, 11, 10, 11]);

% Decision Variables
array[1..num_jobs] of var 0..sum(durations_data): start_time;
var 0..sum(durations_data): makespan;

% Constraints
% Job durations
constraint forall(j in 1..num_jobs) (
    start_time[j] + durations_data[j] <= makespan
);

% Precedence constraints
constraint forall(i in 1..18) (
    start_time[successors_link_data[i, 1]] + durations_data[successors_link_data[i, 1]] <= start_time[successors_link_data[i, 2]]
);

% Resource constraints
constraint forall(t in 0..makespan) (
    forall(r in 1..num_resources) (
        sum(j in 1..num_jobs) (
            (start_time[j] <= t) /\ (start_time[j] + durations_data[j] > t) * resource_needs_data[j, r]
        ) <= resource_capacities_data[r]
    )
);

% Objective: Minimize makespan
solve minimize makespan;

% Output the start times of the jobs
output [
    "{",
    "\"" ++ "start_time" ++ "\": [" ++ join(",", [show(start_time[j]) | j in 1..num_jobs]) ++ "]",
    "}"
