function int: date_to_days(string: date) =
    let {
        array[1..3] of int: parts = [int(s) | s in split("-", date)],
        int: year = parts[1],
        int: month = parts[2],
        int: day = parts[3],
        int: days_in_month[1..12] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31],
        int: leap_days = (year mod 4 == 0 /\ (year mod 100 != 0 \/ year mod 400 == 0))
    } in
        365 * (year - 2024) + sum(i in 1..month - 1) (days_in_month[i] + (if i == 2 then leap_days else 0 endif)) + day;

array[1..4] of int: start_days = [date_to_days(s) | s in start_data];
array[1..4] of int: end_days = [date_to_days(e) | e in end_data];

