    [  % 0 represents empty cells
        [0, 0, 0,  2, 0, 5,  0, 0, 0],
        [0, 9, 0,  0, 0, 0,  7, 3, 0],
        [0, 0, 2,  0, 0, 9,  0, 6, 0],

        [2, 0, 0,  0, 0, 0,  4, 0, 9],
