        [6, 0, 9,  0, 0, 0,  0, 0, 1],

        [0, 8, 0,  4, 0, 0,  1, 0, 0],
        [0, 6, 3,  0, 0, 0,  0, 8, 0],
        [0, 0, 0,  6, 0, 8,  0, 0, 0]
    ];

% Decision variables: the grid to be filled
array[1..n, 1..n] of var 1..n: grid;

% Constraints
% Each cell must match the input grid if it is not empty
constraint forall(i in 1..n, j in 1..n) (
    input_grid[i, j] != 0 -> grid[i, j] = input_grid[i, j]
);

% All numbers in a row must be different
constraint forall(i in 1..n) (
    all_different([grid[i, j] | j in 1..n])
);

% All numbers in a column must be different
constraint forall(j in 1..n) (
    all_different([grid[i, j] | i in 1..n])
);

% All numbers in a 3x3 subgrid must be different
constraint forall(i in 1..s, j in 1..s) (
    all_different([grid[s*(i-1)+k, s*(j-1)+l] | k in 1..s, l in 1..s])
);

% Solve the model
solve satisfy;

% Output the solved grid in JSON format
output [
    "{",
    "\"grid\": [",
    join(",", [join(",", [show(grid[i, j]) | j in 1..n]) | i in 1..n]),
    "]",
    "}"
];
