include "globals.mzn";

% Input data
int: num_cities = 12;
array[1..num_cities, 1..2] of int: locations = [
    (288, 149), (288, 129), (270, 133), (256, 141), (256, 163), (246, 157),
    (236, 169), (228, 169), (228, 148), (220, 164), (212, 172), (204, 159)
];

% Calculate the distance matrix
array[1..num_cities, 1..num_cities] of int: distance;
constraint forall(i in 1..num_cities, j in 1..num_cities) (
    distance[i, j] = abs(locations[i, 1] - locations[j, 1]) + abs(locations[i, 2] - locations[j, 2])
);

% Decision variables
array[1..num_cities] of var 1..num_cities: tour;
var int: travel_distance;

% Constraints
% All cities must be visited exactly once
constraint all_different(tour);

% Subcircuit constraint to ensure the tour is a single cycle
constraint subcircuit(tour);

% Calculate the total travel distance
constraint travel_distance = sum(i in 1..num_cities) (distance[tour[i], tour[i mod num_cities + 1]]);

% Solve the model to minimize the travel distance
solve minimize travel_distance;

% Output the solution in JSON format
output [
    "{",
    "\"" ++ "travel_distance" ++ "\": " ++ show(travel_distance),
    "}"
];
```

