% Input data
set of int: People = 1..3;
string: names[People] = ["Agatha herself", "the butler", "Charles"];

% Decision Variables
var People: killer;
array[People, People] of var bool: hates;
array[People] of var bool: richer_than_agatha;

% Constraints
% A killer always hates, and is no richer than his victim.
constraint hates[killer, 1] /\ not richer_than_agatha[killer];

% Charles hates noone that Agatha hates.
constraint forall(p in People) (hates[3, p] -> not hates[1, p]);

% Agatha hates everybody except the butler.
constraint hates[1, 1] = false;
constraint hates[1, 2] = false;
constraint hates[1, 3] = true;

% The butler hates everyone not richer than Aunt Agatha.
constraint forall(p in People) (hates[2, p] <-> not richer_than_agatha[p]);

% The butler hates everyone whom Agatha hates.
constraint forall(p in People) (hates[2, p] /\ hates[1, p]);

% Noone hates everyone.
constraint forall(p in People) (not all(hates[p, q] | q in People));

solve satisfy;

output ["{\"killer\": ", show(killer), "}"];
```

