array[1..stage] of var 0..1: goat_pos;    % Position of the goat at each stage
array[1..stage] of var 0..1: cabbage_pos; % Position of the cabbage at each stage
array[1..stage] of var 0..1: boat_pos;    % Position of the boat at each stage

% Initial conditions
constraint wolf_pos[1] = 0;
constraint goat_pos[1] = 0;
constraint cabbage_pos[1] = 0;
constraint boat_pos[1] = 0;

% Final conditions
constraint wolf_pos[stage] = 1;
constraint goat_pos[stage] = 1;
constraint cabbage_pos[stage] = 1;
constraint boat_pos[stage] = 1;

% Constraints for each stage
constraint forall(i in 2..stage) (
    % Boat must move
    boat_pos[i] = 1 - boat_pos[i-1] /\

    % If the boat moves, only one item can move with it
    (wolf_pos[i] = wolf_pos[i-1] \/ wolf_pos[i] = boat_pos[i]) /\
    (goat_pos[i] = goat_pos[i-1] \/ goat_pos[i] = boat_pos[i]) /\
    (cabbage_pos[i] = cabbage_pos[i-1] \/ cabbage_pos[i] = boat_pos[i]) /\
    (sum([wolf_pos[i] != wolf_pos[i-1], goat_pos[i] != goat_pos[i-1], cabbage_pos[i] != cabbage_pos[i-1]]) <= 1) /\

    % If the farmer leaves the wolf and goat together, the wolf will eat the goat
    (wolf_pos[i] != goat_pos[i] \/ boat_pos[i] = wolf_pos[i]) /\

    % If the farmer leaves the goat and cabbage together, the goat will eat the cabbage
    (goat_pos[i] != cabbage_pos[i] \/ boat_pos[i] = goat_pos[i])
);

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
