include "globals.mzn";

% Input data
int: n_weeks = 4;  % Number of weeks
int: n_groups = 3;  % Number of groups
int: group_size = 3;  % Size of each group
int: n_golfers = n_groups * group_size;  % Total number of golfers

% Decision Variables
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% Constraints
% Each golfer appears exactly once per week
constraint forall(w in 1..n_weeks, g in 1..n_groups, i in 1..group_size) (
    all_different([assign[w, g, i] | g in 1..n_groups, i in 1..group_size])
);

% Each golfer appears exactly once per group per week
constraint forall(w in 1..n_weeks, g in 1..n_groups) (
    all_different([assign[w, g, i] | i in 1..group_size])
);

% No golfer plays in the same group as any other golfer more than once
constraint forall(w1 in 1..n_weeks, w2 in w1+1..n_weeks, g1 in 1..n_groups, g2 in 1..n_groups) (
    alldifferent_except_0([if assign[w1, g1, i] == assign[w2, g2, j] then 1 else 0 endif | i in 1..group_size, j in 1..group_size])
);

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "assign" ++ "\": [" ++ join(",", [
            "[" ++ join(",", [
                "[" ++ join(",", [show(assign[w, g, i]) | i in 1..group_size]) ++ "]"
            | g in 1..n_groups]) ++ "]"
        | w in 1..n_weeks]) ++ "]"
    ]),
    "}"
];
