include "globals.mzn";

% Input data
int: n_teams = 9;
int: n_days = 18;
set of int: Teams = 1..n_teams;
set of int: Days = 1..n_days;

% Team names for reference
array[Teams] of string: team_names = ["Clem", "Duke", "FSU", "GT", "UMD", "UNC", "NCSt", "UVA", "Wake"];

% Mirroring scheme
array[1..9, 1..2] of int: mirroring = array2d(1..9, 1..2, [1, 8, 2, 9, 3, 12, 4, 13, 5, 14, 6, 15, 7, 16, 10, 17, 11, 18]);

% Rival pairs
array[1..4, 1..2] of int: rivals = array2d(1..4, 1..2, [2, 6, 1, 4, 6, 9, 5, 8]);

% Constrained matches
array[1..4, 1..2] of int: constrained_matches = array2d(1..4, 1..2, [9, 6, 9, 2, 4, 6, 4, 2]);

% Decision Variables
% 1 = home, 2 = away, 3 = bye
array[Teams, Days] of var 1..3: schedule;

% Constraints

% Each team plays each other exactly once at home and once away
constraint forall(i, j in Teams where i < j) (
    sum(d in Days)(bool2int(schedule[i, d] == 1 /\ schedule[j, d] == 2)) = 1 /\
    sum(d in Days)(bool2int(schedule[i, d] == 2 /\ schedule[j, d] == 1)) = 1
);

% Mirroring scheme
constraint forall(m in 1..9) (
    forall(t in Teams) (
        schedule[t, mirroring[m, 1]] = schedule[t, mirroring[m, 2]]
    )
);

% No two final aways
constraint forall(t in Teams) (
    schedule[t, n_days] != 2 \/ schedule[t, n_days - 1] != 2
);

% Home/Away/Bye Pattern Constraints
constraint forall(t in Teams) (
    forall(d in 2..n_days - 1) (
        schedule[t, d] != schedule[t, d - 1] \/ schedule[t, d] != schedule[t, d - 2]
    ) /\
    sum(d in 1..n_days - 2)(bool2int(schedule[t, d] == 2 /\ schedule[t, d + 1] == 2 /\ schedule[t, d + 2] == 2)) = 0 /\
