% Input data
int: n = 13;  % Number of balls
int: c = 3;  % Number of boxes

% Decision Variables
array[1..n, 1..c] of var bool: M;  % M[i,j] is true if ball i is in box j

% Constraints
% Each ball must be in exactly one box
constraint forall(i in 1..n) (
    sum(j in 1..c) (M[i,j]) = 1
);

% For each triple (x, y, z) with x + y = z, not all can be in the same box
constraint forall(j in 1..c) (
    forall(x in 1..n, y in 1..n where x + y <= n) (
        M[x,j] + M[y,j] + M[x+y,j] <= 2
    )
);

% Solve the model
solve satisfy;

% Output the assignment of balls to boxes
output [
    "{",
    "\"balls\": [" ++ join(",", [show(fix(sum(j in 1..c) (j * M[i,j]))) | i in 1..n]) ++ "]",
    "}"
];
