% Include necessary libraries
include "globals.mzn";

% Input data
int: n = 9;  % Order of the Steiner Triple System

% Calculate the number of triples
int: num_triples = n * (n - 1) div 6;

% Decision variables
% triples[i][j] represents the j-th element of the i-th triple
array[1..num_triples, 1..3] of var 1..n: triples;

% Constraints
% All elements in each triple must be distinct
constraint forall(i in 1..num_triples) (
    all_different([triples[i, 1], triples[i, 2], triples[i, 3]])
);

% Each pair of elements appears in at most one triple
constraint forall(i, j in 1..n where i < j) (
    sum(k in 1..num_triples) (
        bool2int(triples[k, 1] = i /\ triples[k, 2] = j) +
        bool2int(triples[k, 1] = i /\ triples[k, 3] = j) +
        bool2int(triples[k, 2] = i /\ triples[k, 3] = j)
    ) <= 1
);

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"sets\": [",
    join(",", [
        "{" ++ join(",", ["\"" ++ show(triples[i, j]) ++ "\"" | j in 1..3]) ++ "}"
        | i in 1..num_triples
    ]),
    "]",
    "}"
];
```

