include "globals.mzn";

% Input data
int: N = 10;  % Number of vertices in the graph

% Decision Variables
array[1..N] of var 1..N: degree;  % Degree sequence
array[1..N, 1..N] of var 0..1: matrix;  % Adjacency matrix

% Constraints
% 1. Degree sequence is non-increasing
constraint forall(i in 1..N-1)(degree[i] >= degree[i+1]);

% 2. Each degree is greater than 0 and modulo 3
constraint forall(i in 1..N)(degree[i] > 0 /\ degree[i] mod 3 = 0);

% 3. The sum of the degrees is modulo 12
constraint sum(degree) mod 12 = 0;

% 4. The sum of the degrees is twice the number of edges
constraint sum(degree) = 2 * sum(i in 1..N, j in i+1..N)(matrix[i, j]);

% 5. The adjacency matrix is symmetric
constraint forall(i in 1..N, j in i+1..N)(matrix[i, j] = matrix[j, i]);

% 6. The adjacency matrix represents a simple graph (no loops)
constraint forall(i in 1..N)(matrix[i, i] = 0);

% 7. The degree of each vertex matches the adjacency matrix
constraint forall(i in 1..N)(degree[i] = sum(j in 1..N)(matrix[i, j]));

% 8. The graph is diamond-free
% For every set of four vertices, the number of edges between them is at most 4
constraint forall(i, j, k, l in 1..N where i < j /\ j < k /\ k < l) (
    matrix[i, j] + matrix[i, k] + matrix[i, l] + matrix[j, k] + matrix[j, l] + matrix[k, l] <= 4
);

solve satisfy;

output [
    "{",
    "\"matrix\": [" ++ join(",", [ "[" ++ join(",", [show(matrix[i, j]) | j in 1..N]) ++ "]" | i in 1..N]) ++ "]",
    "}"
];
```

