% Input data
int: num_tasks = 4;
int: num_people = 5;
array[1..num_tasks, 1..num_people] of int: cost;

% Decision Variables
array[1..num_tasks, 1..num_people] of var 0..1: x; % x[t, p] = 1 if person p is assigned to task t, 0 otherwise
array[1..num_tasks] of var 1..num_people: assigned_person; % assigned_person[t] is the person assigned to task t
array[1..num_people] of var 0..1: is_assigned; % is_assigned[p] = 1 if person p is assigned to any task, 0 otherwise

% Constraints
% Each task must be assigned to exactly one person
constraint forall(t in 1..num_tasks) (
    sum(p in 1..num_people) (x[t, p]) = 1
);

% Each person can be assigned to at most one task
constraint forall(p in 1..num_people) (
    sum(t in 1..num_tasks) (x[t, p]) <= 1
);

% Define assigned_person based on x
constraint forall(t in 1..num_tasks) (
    assigned_person[t] = sum(p in 1..num_people) (p * x[t, p])
);

% Define is_assigned based on x
constraint forall(p in 1..num_people) (
    is_assigned[p] = sum(t in 1..num_tasks) (x[t, p])
);

% Objective function: minimize the total cost
solve minimize sum(t in 1..num_tasks, p in 1..num_people) (cost[t, p] * x[t, p]);

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "x" ++ "\": [" ++ join(",", [join(",", [show(x[t, p]) | p in 1..num_people]) | t in 1..num_tasks]) ++ "]"
    ]),
    "}"
];
