    1, 3,  % Rock(1) crushes Scissors(3)
    1, 4,  % Rock(1) crushes Lizard(4)
    2, 1,  % Paper(2) covers Rock(1)
    2, 5,  % Paper(2) disproves Spock(5)
    3, 2,  % Scissors(3) cuts Paper(2)
    3, 4,  % Scissors(3) decapitate Lizard(4)
    4, 2,  % Lizard(4) eats Paper(2)
    4, 5,  % Lizard(4) poisons Spock(5)
    5, 1,  % Spock(5) vaporizes Rock(1)
    5, 3   % Spock(5) smashes Scissors(3)
]);

% Decision Variables
array[Dice, Faces] of var 1..6: dice;

% Constraints
% Each die must have unique faces
constraint forall(d in Dice) (
    all_different([dice[d, f] | f in Faces])
);

% Implement the beats relationships
constraint forall(b in 1..10) (
    let {
        int: winner = beats[b, 1];
        int: loser = beats[b, 2];
        var Faces: winner_face;
        var Faces: loser_face;
    } in
    exists(winner_face in Faces) (
        exists(loser_face in Faces) (
            dice[winner, winner_face] > dice[loser, loser_face] /\
            forall(f in Faces where f != winner_face) (
                dice[winner, f] <= dice[loser, loser_face]
            ) /\
            forall(f in Faces where f != loser_face) (
                dice[loser, f] < dice[winner, winner_face]
            )
        )
    )
);

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
    "\"dice\": [" ++ join(",", [show([dice[d, f] | f in Faces]) | d in Dice]) ++ "]",
    "}"
];
